use crate::{editor::{Action,Editor},scene::Scene};
use std::rc::Rc;
fn editor()->Editor{let mut e=Editor::default();e.apply(Action::Close).unwrap();e}
fn command(e:&mut Editor,line:&str)->Result<(),String>{let action=if let Some(a)=e.tool_line(line){a.map_err(str::to_owned)?}else{let crate::commands::Command::Editor(a)=crate::commands::parse(line)? else{return Err("Editor command".into())};a};e.apply(action).map_err(|message|if message=="Shape input invalid"{e.tool_status.clone()}else{message.into()})?;Ok(())}
#[test]
fn original_loft_options_keep_order_placement_sources_one_undo_and_exact_archive(){
    let mut e=editor();for line in ["Curve w-1,-1,0 w0,-1,1 w1,-1,0","Curve w-1,0,0 w0,0,2 w1,0,0","Curve w-1,1,0 w0,1,1 w1,1,0"]{command(&mut e,line).unwrap()}let ids=e.scene.paths().iter().map(|r|r.id).collect::<Vec<_>>();let originals=e.scene.paths().iter().map(|r|r.prepared.source.clone()).collect::<Vec<_>>();for id in &ids{e.scene.place_following(*id,session_rust::Xform::translation(10.,0.,0.)).unwrap()}e.select_objects(ids.clone(),false);command(&mut e,"Nurbs Surface Loft Straight").unwrap();let surface=e.scene.objects()[0].surface.as_ref().unwrap().source.clone();assert_eq!(surface.degree(1),1);let b=e.scene.selected_bounds(e.scene.objects()[0].id).unwrap();assert!((b.min[0]-9.).abs()<1e-6&&(b.max[0]-11.).abs()<1e-6);let _=surface.guid();let proto=surface.to_proto();let bytes=crate::scene_archive::save(&e.scene).unwrap();let mut saved=Scene::empty();crate::scene_document::open(&mut saved,&bytes).unwrap();assert_eq!(saved.objects()[0].surface.as_ref().unwrap().source.to_proto(),proto);assert_eq!(saved.paths().len(),3);command(&mut e,"Undo").unwrap();assert!(e.scene.objects().is_empty());e.select_objects(ids,false);command(&mut e,"Nurbs Surface Loft Smooth").unwrap();assert!(e.scene.objects()[0].surface.as_ref().unwrap().source.degree(1)>1);for(row,source)in e.scene.paths().iter().zip(originals){assert!(matches!((&row.prepared.source,source),(crate::chain::Source::Curve(a,_),crate::chain::Source::Curve(b,_))if Rc::ptr_eq(a,&b)))}
}
#[test]
fn closed_loft_short_input_refuses_before_adoption_and_retains_redo_and_cancel_selection(){
    let mut e=editor();command(&mut e,"Polyline w0,0,0 w1,0,0 w1,1,0 w0,1,0 w0,0,0").unwrap();command(&mut e,"Polyline w0,0,1 w1,0,1 w1,1,1 w0,1,1 w0,0,1").unwrap();command(&mut e,"Point w4,0,0").unwrap();command(&mut e,"Undo").unwrap();let ids=e.scene.paths().iter().map(|r|r.id).collect::<Vec<_>>();e.select_objects(ids.clone(),false);assert!(command(&mut e,"Loft Closed").is_err());assert!(e.draft.is_none());assert_eq!(e.selected_objects(),ids);assert!(e.scene.objects().is_empty());command(&mut e,"Redo").unwrap();assert_eq!(e.scene.points().len(),1);e.select_objects([],false);command(&mut e,"Loft").unwrap();e.apply(Action::GatherPick(Some(ids[0]))).unwrap();assert!(command(&mut e,"").is_err());assert_eq!(e.draft.as_ref().unwrap().gather.as_ref().unwrap().progress.rows[0],vec![ids[0].value()]);command(&mut e,"Escape").unwrap();assert!(e.selected_objects().is_empty());
}
#[test]
fn one_rail_pick_advances_automatically_and_cannot_be_reused_as_a_profile(){
    let mut e=editor();command(&mut e,"Line w0,0,0 w3,0,0").unwrap();command(&mut e,"Polyline w0,-0.2,-0.2 w0,0.2,-0.2 w0,0.2,0.2 w0,-0.2,0.2 w0,-0.2,-0.2").unwrap();let rail=e.scene.lines()[0].id;let profile=e.scene.paths()[0].id;command(&mut e,"Nurbs Surface Sweep1").unwrap();e.apply(Action::GatherPick(Some(rail))).unwrap();assert_eq!(e.draft.as_ref().unwrap().gather.as_ref().unwrap().progress.step,1);assert!(e.apply(Action::GatherPick(Some(rail))).is_err());e.apply(Action::GatherPick(Some(profile))).unwrap();command(&mut e,"").unwrap();assert!(e.scene.objects()[0].surface.as_ref().unwrap().source.is_closed(0));assert_eq!(e.scene.paths().len(),1);assert_eq!(e.scene.lines().len(),1);command(&mut e,"Undo").unwrap();assert!(e.scene.objects().is_empty());command(&mut e,"Redo").unwrap();assert_eq!(e.scene.objects().len(),1);
}
#[test]
fn two_rail_preselection_keeps_group_order_original_shapes_and_aliases(){
    let mut e=editor();for line in ["Line w0,0,0 w3,0,0","Line w0,1,0 w3,1,0.5","Curve w0,0,0 w0,0.5,0.3 w0,1,0"]{command(&mut e,line).unwrap()}let ids=vec![e.scene.lines()[0].id,e.scene.lines()[1].id,e.scene.paths()[0].id];let source=e.scene.lines()[1].prepared.source.clone();let original=source.to_proto();e.select_objects(ids,false);command(&mut e,"NURBSSURFACE_SWEEP2").unwrap();assert!(e.draft.is_none());assert_eq!(e.scene.objects().len(),1);assert!(e.scene.objects()[0].surface.as_ref().unwrap().source.is_valid());assert_eq!(source.to_proto(),original);assert!(Rc::ptr_eq(&source,&e.scene.lines()[1].prepared.source));command(&mut e,"Undo").unwrap();assert!(e.scene.objects().is_empty());assert_eq!(crate::commands::canonical("nurbssurface_sweep1"),"Nurbs Surface Sweep1");assert_eq!(crate::commands::canonical("nurbssurface_loft Straight"),"Nurbs Surface Loft Straight");assert_eq!(crate::commands::canonical("nurbssurface_revolve"),"Nurbs Surface Revolve");
}
